15.     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
16.     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
17.         labelColumnName: "Label", featureColumnName: "Features"));
18. 
19. // Use cross-validation for small datasets; switch to TrainTestSplit with larger data
20. var cvResults = mlContext.BinaryClassification.CrossValidate(dataView, pipeline, numberOfFolds: 3, labelColumnName: "Label");
21. var avgAuc = cvResults.Average(r => r.Metrics.AreaUnderRocCurve);
22. var avgF1 = cvResults.Average(r => r.Metrics.F1Score);
23. Console.WriteLine($"Cross-validation metrics — Avg AUC: {avgAuc:F4}, Avg F1: {avgF1:F4}");
24. 
25. // Train final model on all data
