1. using Microsoft.ML;
2. using Microsoft.ML.Data;
3. using Microsoft.Extensions.ML;
4. using ChurnPredictor;
5. 
6. var builder = WebApplication.CreateBuilder(args);
7. 
8. // Train the model and register the prediction engine pool
9. var mlContext = new MLContext(seed: 42);
10. var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
11. var dataView = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');
12. 
13. var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region))
14.     .Append(mlContext.Transforms.Concatenate("Features", nameof(CustomerData.Age), nameof(CustomerData.Income), "RegionEncoded", nameof(CustomerData.PurchaseHistory)))
15.     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
16.     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
17.         labelColumnName: "Label", featureColumnName: "Features"));
18. 
19. // Use cross-validation for small datasets; switch to TrainTestSplit with larger data
20. var cvResults = mlContext.BinaryClassification.CrossValidate(dataView, pipeline, numberOfFolds: 3, labelColumnName: "Label");
21. var avgAuc = cvResults.Average(r => r.Metrics.AreaUnderRocCurve);
22. var avgF1 = cvResults.Average(r => r.Metrics.F1Score);
23. Console.WriteLine($"Cross-validation metrics — Avg AUC: {avgAuc:F4}, Avg F1: {avgF1:F4}");
24. 
25. // Train final model on all data
26. var model = pipeline.Fit(dataView);
27. 
28. // Save model and register pooled prediction engine
29. var modelPath = Path.Combine(AppContext.BaseDirectory, "churn_model.zip");
30. mlContext.Model.Save(model, dataView.Schema, modelPath);
31. 
32. builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
33.     .FromFile(modelPath);
34. 
35. var app = builder.Build();
36. 
37. app.MapPost("/predict", (PredictionEnginePool<CustomerData, ChurnPrediction> pool, CustomerRequest request) =>
38. {
39.     var input = new CustomerData
40.     {
41.         Age = request.Age,
42.         Income = request.Income,
43.         Region = request.Region,
44.         PurchaseHistory = request.PurchaseHistory
45.     };
46.     var prediction = pool.Predict(input);
47.     return Results.Ok(new { WillChurn = prediction.PredictedLabel, Probability = prediction.Probability });
48. });
49. 
50. app.Run();
51. 
